def install_window_icon(root):
    # Keep images alive for the lifetime of this window.
    root.afterglow_icons = [tk.PhotoImage(master=root, data=encoded)
                           for size, encoded in ICONS if size in (32, 256)]
    root.iconphoto(True, *root.afterglow_icons)


def ico_bytes():
    images = [(size, base64.b64decode(encoded)) for size, encoded in ICONS]
    offset = 6 + 16 * len(images)
    directory = bytearray(struct.pack("<HHH", 0, 1, len(images)))
    for size, content in images:
        directory.extend(struct.pack("<BBBBHHII", size % 256, size % 256,
                                     0, 0, 1, 32, len(content), offset))
        offset += len(content)
    return bytes(directory) + b"".join(content for _, content in images)


if __name__ == "__main__":
    Path(__file__).with_name("afterglow.local.ico").write_bytes(ico_bytes())
